#### Phase 2: Build and Publish Pipeline

**Step 1: Azure DevOps Pipeline Configuration**

```yaml
# azure-pipelines.yml
trigger:
  branches:
    include:
      - main
      - release/**
  tags:
    include:
      - v*

variables:
  buildConfiguration: 'Release'
  packageFeed: 'Gainwell-Customizations'

stages:
- stage: Build
  jobs:
  - job: BuildPackage
    pool:
      vmImage: 'windows-latest'

    steps:
    - task: UseDotNet@2
      inputs:
        version: '6.0.x'

    - task: DotNetCoreCLI@2
      displayName: 'Restore Dependencies'
      inputs:
        command: 'restore'
        projects: '**/*.csproj'

    - task: DotNetCoreCLI@2
      displayName: 'Build Solution'
      inputs:
        command: 'build'
        projects: '**/*.csproj'
        arguments: '--configuration $(buildConfiguration) --no-restore'

    - task: DotNetCoreCLI@2
      displayName: 'Run Unit Tests'
      inputs:
        command: 'test'
        projects: '**/*Tests.csproj'
        arguments: '--configuration $(buildConfiguration) --no-build --collect:"Code Coverage"'

    - task: PowerShell@2
      displayName: 'Determine Version'
      inputs:
        targetType: 'inline'
        script: |
          $version = "1.0.0"
          if ($env:BUILD_SOURCEBRANCH -match "refs/tags/v(.*)")
          {
            $version = $matches[1]
          }
          elseif ($env:BUILD_SOURCEBRANCH -match "refs/heads/release/(.*)")
          {
            $version = "$($matches[1])-beta$env:BUILD_BUILDID"
          }
          else
          {
            $version = "1.0.0-alpha$env:BUILD_BUILDID"
          }
          Write-Host "##vso[task.setvariable variable=PackageVersion]$version"

    - task: DotNetCoreCLI@2
      displayName: 'Create NuGet Package'
      inputs:
        command: 'pack'
        packagesToPack: '**/StateA.ClaimsProcessing.csproj'
        configuration: '$(buildConfiguration)'
        packDirectory: '$(Build.ArtifactStagingDirectory)'
        versioningScheme: 'byEnvVar'
        versionEnvVar: 'PackageVersion'
        includeSymbols: true

    - task: NuGetCommand@2
      displayName: 'Sign Package'
      inputs:
        command: 'custom'
        arguments: 'sign $(Build.ArtifactStagingDirectory)\*.nupkg -CertificatePath $(Agent.TempDirectory)\cert.pfx -CertificatePassword $(CertPassword) -Timestamper http://timestamp.digicert.com'

    - task: PublishBuildArtifacts@1
      displayName: 'Publish Package Artifact'
      inputs:
        pathToPublish: '$(Build.ArtifactStagingDirectory)'
        artifactName: 'packages'

- stage: Publish
  dependsOn: Build
  condition: and(succeeded(), or(startsWith(variables['Build.SourceBranch'], 'refs/tags/v'), startsWith(variables['Build.SourceBranch'], 'refs/heads/release/')))
  jobs:
  - job: PublishPackage
    steps:
    - task: DownloadBuildArtifacts@0
      inputs:
        artifactName: 'packages'

    - task: NuGetCommand@2
      displayName: 'Push to Azure Artifacts'
      inputs:
        command: 'push'
        packagesToPush: '$(Build.ArtifactStagingDirectory)/packages/*.nupkg'
        nuGetFeedType: 'internal'
        publishVstsFeed: '$(packageFeed)'
```

**Step 2: Semantic Version Calculation**

```powershell
# calculate-version.ps1
function Get-SemanticVersion {
    param(
        [string]$BranchName,
        [string]$BuildId
    )

    # Check if this is a tagged release
    if ($BranchName -match "refs/tags/v(\d+\.\d+\.\d+)$") {
        return $matches[1]
    }

    # Check if this is a release branch
    if ($BranchName -match "refs/heads/release/(\d+\.\d+)") {
        return "$($matches[1]).0-rc$BuildId"
    }

    # Development build
    $majorMinor = Get-MajorMinorFromFile
    return "$majorMinor.0-dev$BuildId"
}

function Get-MajorMinorFromFile {
    # Read from version.txt or Directory.Build.props
    $props = [xml](Get-Content "Directory.Build.props")
    $version = $props.Project.PropertyGroup.VersionPrefix
    return $version
}
```

**Step 3: Package Validation**

```csharp
public class PackageValidator
{
    public async Task<ValidationResult> ValidatePackageAsync(string packagePath)
    {
        var errors = new List<string>();

        // Validate package can be opened
        using var package = new ZipPackage(packagePath);

        // Validate metadata.json exists
        if (!package.FileExists("metadata.json"))
        {
            errors.Add("Missing required metadata.json file");
        }
        else
        {
            var metadata = await package.ReadMetadataAsync();

            // Validate semantic versioning
            if (!SemanticVersion.TryParse(metadata.Version, out _))
            {
                errors.Add($"Invalid semantic version: {metadata.Version}");
            }

            // Validate IP ownership
            if (string.IsNullOrEmpty(metadata.IpOwnership))
            {
                errors.Add("IP ownership must be specified");
            }

            // Validate compatibility version range
            if (string.IsNullOrEmpty(metadata.Compatibility.MinimumProductVersion))
            {
                errors.Add("Minimum product version must be specified");
            }
        }

        // Validate package is signed
        if (!await IsPackageSignedAsync(packagePath))
        {
            errors.Add("Package must be digitally signed");
        }

        return new ValidationResult
        {
            IsValid = !errors.Any(),
            Errors = errors
        };
    }
}
